class NoteViewSet(viewsets.ModelViewSet):
    serializer_class = NoteSerializer
    permission_classes = [IsAuthenticated, IsOwner]

    def get_queryset(self):
        # اگر ادمین است، همه را ببیند
        if self.request.user.is_staff:
            return Note.objects.all()
        # وگرنه فقط یادداشت‌های خودش
        # این خط باعث می‌شود به یادداشت دیگران 404 بدهد، نه 403
        return Note.objects.filter(owner=self.request.user)

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)

from rest_framework.permissions import BasePermission, SAFE_METHODS


def has_group(user, name):
    if not user.is_authenticated:
        return False
    return user.groups.filter(name=name).exists()


class IsWriterOrReadOnly(BasePermission):
    message = "فقط نویسندگان می‌توانند مقاله بسازند."

    def has_permission(self, request, view):
        if request.method in SAFE_METHODS:
            return True
        return has_group(request.user, "writer") or request.user.is_staff


class IsEditor(BasePermission):
    message = "فقط ویرایشگرها مجاز هستند."

    def has_permission(self, request, view):
        return has_group(request.user, "editor") or request.user.is_staff


class CanEditArticle(BasePermission):
    message = "شما اجازه ویرایش این مقاله را ندارید."

    def has_object_permission(self, request, view, obj):
        if request.method in SAFE_METHODS:
            return True
        if request.user.is_staff:
            return True
        if obj.is_published:
            return has_group(request.user, "editor")
        return obj.author == request.user

from rest_framework import viewsets
from rest_framework.decorators import action
from rest_framework.permissions import AllowAny, IsAdminUser, IsAuthenticated
from rest_framework.response import Response
from django.utils import timezone
from .models import Article
from .serializers import ArticleSerializer
from .permissions import IsWriterOrReadOnly, IsEditor, CanEditArticle


class ArticleViewSet(viewsets.ModelViewSet):
    queryset = Article.objects.select_related("author").all()
    serializer_class = ArticleSerializer

    def get_permissions(self):
        if self.action in ("list", "retrieve"):
            return [AllowAny()]
        if self.action == "create":
            return [IsWriterOrReadOnly()]
        if self.action == "destroy":
            return [IsAdminUser()]
        if self.action == "publish":
            return [IsEditor()]
        if self.action in ("update", "partial_update"):
            return [IsAuthenticated(), CanEditArticle()]
        return [IsAuthenticated()]

    def perform_create(self, serializer):
        serializer.save(author=self.request.user)

    @action(detail=True, methods=["post"])
    def publish(self, request, pk=None):
        article = self.get_object()
        article.is_published = True
        article.published_at = timezone.now()
        article.save(update_fields=["is_published", "published_at"])
        return Response({"status": "published"})

from django.conf import settings
from django.db import models
from django.db.models.signals import post_save
from django.dispatch import receiver


class Profile(models.Model):
    user = models.OneToOneField(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="profile",
    )
    bio = models.TextField(blank=True)
    phone = models.CharField(max_length=20, blank=True)
    avatar = models.ImageField(upload_to="avatars/", blank=True, null=True)
    created_at = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return f"Profile of {self.user.username}"


@receiver(post_save, sender=settings.AUTH_USER_MODEL)
def create_profile(sender, instance, created, **kwargs):
    if created:
        Profile.objects.create(user=instance)

